INSERT INTO `plans` (`id`, `position`, `title`, `category`, `description`) VALUES
	('when-discouragement-weighs', 0, 'Quando o desânimo pesar', 'emotions', 'Um plano curto para te ajudar a respirar, organizar os pensamentos e reencontrar pequenos motivos para continuar.'),
	('after-a-rejection', 1, 'Depois de uma rejeição', 'emotions', 'Sete dias para acolher a dor da rejeição, recuperar o valor que você tem e seguir em frente com o coração em paz.'),
	('learning-to-set-boundaries', 2, 'Aprendendo a colocar limites', 'relationships', 'Sete dias para reconhecer seus limites, dizer não com gentileza e se aproximar de quem você realmente é.'),
	('when-your-faith-is-tired', 3, 'Quando sua fé estiver cansada', 'faith', 'Cinco dias para quem está cansada de esperar, acolher as dúvidas e reencontrar a presença de Deus no cotidiano.'),
	('finding-direction-again', 4, 'Encontrando direção novamente', 'faith', 'Sete dias para acalmar a mente, ouvir o que importa e dar o próximo passo com mais clareza e confiança.');
INSERT INTO `plan_days` (`plan_id`, `day_number`, `title`, `summary`, `message`, `reflection`, `action`, `tip`, `prayer`, `video_duration_seconds`) VALUES
	('when-discouragement-weighs', 1, 'Respirar e reconhecer', 'Pare por um instante e reconheça como você realmente está hoje.', 'Antes de exigir força de você, vamos aprender a respirar. Nem todo dia precisa ser produtivo. Hoje, o convite é apenas reconhecer como você está e se permitir um novo começo.', 'O que o seu corpo está tentando dizer agora? Talvez cansaço, talvez tristeza, talvez só a falta de um respiro. Dar nome ao que você sente não é fraqueza: é o primeiro passo para cuidar de si com verdade e sem pressa.', 'Respire fundo cinco vezes, contando até quatro ao inspirar e ao soltar o ar.', 'Reconhecer o que sente não obriga você a resolver tudo agora.', 'Senhor, hoje eu chego cansada e quero ser honesta contigo. Acolhe o meu cansaço, acalma o meu coração e me ajuda a respirar. Mostra-me que não preciso carregar tudo sozinha. Dá-me descanso e um novo começo, no meu ritmo. Amém.', 138),
	('when-discouragement-weighs', 2, 'Pequenos movimentos', 'Quando o todo parece grande demais, comece por um gesto pequeno.', 'O desânimo faz tudo parecer enorme, e por isso o caminho é diminuir o tamanho do passo. Você não precisa resolver a semana inteira. Hoje, escolha um único movimento possível e deixe que ele seja suficiente para este dia.', 'Qual é a menor coisa que você poderia fazer hoje e que já seria um avanço? Abrir a janela, responder uma mensagem, caminhar até a esquina. Pequenos movimentos também são movimento, e contam.', 'Escolha uma tarefa de cinco minutos e faça só ela, sem cobrar mais nada.', 'Passos pequenos também chegam longe, principalmente quando são constantes.', 'Pai, a minha força é pouca, mas o meu desejo de seguir é verdadeiro. Ensina-me a dar um passo de cada vez e a confiar que estás comigo no caminho. Que eu não despreze os pequenos começos, porque tu os abençoas. Amém.', 120),
	('when-discouragement-weighs', 3, 'Voltar a acreditar', 'Reencontre, com delicadeza, os motivos que ainda sustentam você.', 'Acreditar de novo não acontece de uma vez. Começa quando você lembra de algo que já superou, de alguém que torce por você, de uma esperança pequena que insiste em ficar. Hoje, deixe esses motivos virem, sem pressa e sem comparação.', 'Pense em um momento difícil que você já atravessou. O que a sustentou naquela época? Essa mesma força continua com você, mesmo quando não parece. Você já foi mais forte do que imaginava.', 'Escreva três motivos, por menores que sejam, para seguir em frente.', 'Esperança não é certeza do amanhã, é a coragem de dar mais um passo.', 'Deus de esperança, renova em mim a confiança de que o meu caminho tem sentido. Quando eu duvidar, lembra-me do que já fizeste na minha vida. Que eu volte a acreditar, com calma, e a caminhar em paz contigo. Amém.', 150),
	('after-a-rejection', 1, 'Acolher a dor', 'Dói, e está tudo bem em sentir isso hoje.', 'Ser rejeitada machuca, e não é preciso disfarçar. Antes de buscar explicações ou seguir em frente, permita-se sentir o que veio. A dor que é acolhida pesa menos do que a que é escondida. Hoje, o convite é apenas ficar com você.', 'Onde, no seu corpo, você sente essa rejeição? Perceba sem julgar. Talvez seja um aperto no peito ou um cansaço na garganta. Reconhecer onde dói ajuda a tratar a ferida com mais cuidado e menos pressa.', 'Escreva em poucas linhas o que você sentiu, sem corrigir nem se justificar.', 'Sentir não é fraqueza. É a forma de a dor passar sem ficar presa em você.', 'Senhor, tu conheces a minha dor antes mesmo de eu falar. Hoje não quero fingir que estou bem. Acolhe o meu coração machucado, consola-me com a tua presença e me ajuda a atravessar este dia com ternura por mim mesma. Amém.', 140),
	('after-a-rejection', 2, 'Você não é a rejeição', 'Um não de alguém não define quem você é.', 'Uma rejeição fala de uma situação, de um momento, de uma escolha de outra pessoa. Ela não diz quem você é nem quanto vale. Seu valor não depende de aprovação, porque ele foi dado antes de qualquer resposta que você tenha recebido.', 'Que frase a rejeição repete na sua cabeça? Perceba se ela é um fato ou uma conclusão apressada. Você merece um olhar tão justo consigo quanto o que daria a uma amiga na mesma situação.', 'Troque uma frase dura sobre você por uma que diria a uma amiga querida.', 'O não de alguém não é o veredito sobre o seu valor.', 'Pai, tu me conheces e me chamas de filha amada. Quando as vozes de fora me disserem que sou pouco, lembra-me de quem eu sou em ti. Firma o meu valor na tua graça e cura as palavras que me ferem por dentro. Amém.', 130),
	('after-a-rejection', 3, 'Soltar a história', 'Perceba as histórias que a mente cria e devolva-as ao tamanho real.', 'Depois de uma rejeição, a mente tenta explicar tudo, repete conversas e imagina finais diferentes. Isso cansa. Hoje, tente notar quando começar a girar nas mesmas ideias e, com gentileza, traga a atenção de volta para o que está ao seu alcance.', 'O que você tem repassado sem parar? Há perguntas que talvez nunca tenham resposta, e tudo bem. Soltar não é esquecer: é decidir não alimentar o que só machuca. Você pode descansar de entender tudo.', 'Quando o pensamento voltar, respire e diga: por agora, eu o deixo ir.', 'Você pode soltar uma história sem precisar ter todas as respostas.', 'Senhor, entrego a ti os pensamentos que giram sem parar e as perguntas que não consigo responder. Dá-me a paz que ultrapassa o entendimento e ensina-me a descansar no que está em tuas mãos. Amém.', 125),
	('after-a-rejection', 4, 'Cuidar de si mesma', 'Hoje o foco é você: corpo, descanso e gestos de carinho.', 'Quem foi rejeitada costuma ser dura consigo mesma. Hoje, inverta isso. Cuide do corpo como cuidaria de alguém que ama: alimente-se bem, durma, tome um banho demorado. Cuidar de si não é egoísmo, é a base para você se reerguer.', 'Do que você mais precisa agora: descanso, companhia, silêncio, movimento? Responda com sinceridade e sem culpa. Atender uma necessidade simples já é um ato de respeito por você e pela pessoa que você está se tornando.', 'Faça algo só por prazer hoje, mesmo que por quinze minutos.', 'Cuidar de você não precisa ser grande, só precisa ser verdadeiro.', 'Deus, ensina-me a cuidar do corpo e da alma que me deste. Que eu descanse sem culpa, aceite carinho sem desconfiar e me trate com a mesma bondade com que tu me tratas. Renova as minhas forças hoje. Amém.', 160),
	('after-a-rejection', 5, 'Reencontrar sua voz', 'Lembre do que é importante para você e volte a dizer isso em voz alta.', 'Quando somos rejeitadas, muitas vezes passamos a falar menos, a pedir menos, a ocupar menos espaço. Hoje, retome a sua voz. Lembre do que você gosta, do que valoriza e do que deseja, e permita-se dizer isso sem pedir desculpas.', 'Em que situações você tem se calado para evitar novas feridas? Você pode ser cuidadosa sem se esconder. Sua opinião, seus sonhos e seus limites têm lugar, e quem a valoriza vai querer ouvi-los.', 'Diga em voz alta, para alguém ou para o espelho, algo que você quer.', 'Sua voz não precisa ser alta, só precisa ser sua.', 'Senhor, devolve-me a coragem de ser quem eu sou. Tira o medo de ocupar o meu lugar e de expressar o que sinto. Que as minhas palavras sejam verdadeiras e gentis, e que eu confie que tu me ouves sempre. Amém.', 135),
	('after-a-rejection', 6, 'Perdoar com limites', 'Perdoar é libertar o seu coração, sem se expor de novo.', 'Perdoar não significa esquecer, nem voltar a se aproximar de quem machucou. É decidir não carregar o peso do ressentimento. Você pode perdoar e, ao mesmo tempo, manter distância. O perdão é um processo, e cada pessoa vive o seu no próprio tempo.', 'Há alguma mágoa que ainda pesa em você? Perdoar pode começar com um simples desejo de se libertar dela. Não precisa ser hoje por inteiro. Basta abrir uma pequena porta para que a paz entre aos poucos.', 'Escreva uma frase de perdão que você consiga dizer com sinceridade hoje.', 'Perdoar é um presente para você e não exige que tudo volte ao que era.', 'Pai, tu me perdoaste tanto, e ainda assim é difícil soltar a mágoa. Ajuda-me a perdoar no meu tempo, sem me expor ao que me fere. Cura o meu coração e enche-o da tua paz e da tua misericórdia. Amém.', 145),
	('after-a-rejection', 7, 'Seguir com o coração leve', 'Olhe para trás com gratidão e para frente com abertura.', 'Você chegou ao fim desta caminhada. A dor talvez não tenha desaparecido por completo, e não há problema. Perceba o quanto você já se acolheu nestes dias. Siga adiante com mais gentileza consigo e com a certeza de que ainda há espaço para coisas boas.', 'O que você aprendeu sobre si nesta semana? Reconheça a sua força, a sua sensibilidade e a sua coragem de sentir. Esse caminho foi seu, e você o percorreu. Leve consigo o que fez bem e deixe o resto descansar.', 'Anote uma coisa que você aprendeu sobre si e uma que quer levar adiante.', 'Seguir em frente não é apagar o que doeu, é caminhar com mais cuidado.', 'Senhor, agradeço por cada passo destes dias. Leva contigo o que ainda dói e guarda em mim o que aprendi. Conduz-me com o coração leve para o que vem pela frente, certa de que estás comigo. Amém.', 155),
	('learning-to-set-boundaries', 1, 'Reconhecer seus limites', 'Perceba onde você diz sim quando gostaria de dizer não.', 'Limites são a linha que protege o que é importante para você: seu tempo, sua energia e seus valores. Muitas vezes só os percebemos quando já passaram do ponto. Hoje, comece apenas observando onde você se sente desconfortável ou esgotada.', 'Em que situações você diz sim por medo de decepcionar? Perceba o desconforto no corpo, o cansaço depois, o ressentimento silencioso. Esses sinais não são egoísmo: são avisos de que algo precisa de mais cuidado.', 'Diga um “não” pequeno para algo que você faria apenas para não desagradar.', 'Colocar limites não é se afastar das pessoas, é se aproximar de quem realmente você é.', 'Senhor, dá-me clareza para enxergar onde preciso de limites e coragem para respeitá-los. Ensina-me que cuidar do meu coração é também cuidar de quem eu amo. Que eu seja firme e gentil, como tu és comigo. Amém.', 125),
	('learning-to-set-boundaries', 2, 'Dizer não sem culpa', 'Um não claro e gentil também é uma forma de cuidado.', 'Dizer não pode causar culpa, principalmente para quem aprendeu a agradar. Mas um não honesto é melhor do que um sim ressentido. Você não precisa justificar demais nem pedir desculpas por existir. Pode ser breve, gentil e firme ao mesmo tempo.', 'Qual é a culpa que aparece quando você pensa em recusar algo? Pergunte-se de onde ela vem. Muitas vezes é um hábito antigo, e não uma prova de que você esteja errada. Você pode sentir culpa e, ainda assim, agir com respeito por si.', 'Pratique uma frase simples: agradeço o convite, mas hoje não vai dar.', 'Um não curto e sincero vale mais do que um sim que esgota.', 'Pai, liberta-me da necessidade de agradar a todos. Ensina-me a falar a verdade com amor e a confiar que o teu cuidado não depende da aprovação dos outros. Dá-me paz quando eu disser não. Amém.', 140),
	('learning-to-set-boundaries', 3, 'Escutar o seu corpo', 'Seu corpo avisa antes de você: aprenda a ouvi-lo.', 'O corpo costuma perceber um limite antes da mente: um aperto no peito, a respiração curta, o cansaço repentino. Hoje, preste atenção a esses sinais ao longo do dia. Eles mostram onde você está dando mais do que pode, e são um bom guia.', 'Em que momentos do dia o seu corpo se fechou ou se cansou? Perceba o que estava acontecendo ali. Ouvir esses sinais não é exagero: é uma forma de se respeitar e de decidir com mais clareza o que cabe na sua vida.', 'Três vezes hoje, pare e pergunte ao seu corpo como ele está.', 'O desconforto é uma informação, não um defeito seu.', 'Senhor, tu me formaste com cuidado, corpo e alma. Torna-me atenta aos sinais que me dás e ensina-me a respeitar o meu cansaço. Que eu descanse em ti e escolha com sabedoria onde gastar as minhas forças. Amém.', 130),
	('learning-to-set-boundaries', 4, 'Pedir o que você precisa', 'Dizer com clareza o que precisa também é um limite.', 'Limites não são só recusas; também são pedidos. Pedir ajuda, tempo ou respeito é uma forma de dizer onde você está. Quem te quer bem prefere saber do que precisa a adivinhar. Hoje, pratique pedir algo com simplicidade e sem rodeios.', 'Há algo que você espera que os outros percebam sem você dizer? Muitas frustrações nascem do que ficou calado. Você tem o direito de pedir, e o outro tem o direito de responder. Falar abre espaço para um encontro mais honesto.', 'Peça uma coisa pequena de que precisa a alguém de confiança.', 'Pedir com clareza é um gesto de confiança, não de fraqueza.', 'Deus, ajuda-me a expressar o que preciso sem medo de incomodar. Tira de mim a ideia de que devo me virar sozinha e ensina-me a receber. Que as minhas relações sejam lugares de verdade, respeito e cuidado. Amém.', 135),
	('learning-to-set-boundaries', 5, 'Lidar com a reação alheia', 'Nem toda reação do outro é sinal de que você errou.', 'Quando você começa a colocar limites, algumas pessoas podem estranhar, insistir ou se chatear. Isso é comum, principalmente com quem se acostumou ao seu sempre sim. A reação delas é delas. Você pode ouvir com respeito e, ainda assim, manter o que decidiu.', 'Qual reação você mais teme ao dizer não? Imagine-se respondendo com calma, sem se defender demais. Você pode reconhecer o sentimento do outro sem abrir mão do seu limite. Firmeza e delicadeza podem caminhar juntas.', 'Ensaie uma resposta calma para o caso de alguém insistir.', 'Você pode ser compreensiva com o outro e fiel ao seu limite.', 'Senhor, dá-me serenidade quando alguém não gostar dos meus limites. Guarda o meu coração da culpa que não é minha e da dureza que não quero ter. Ensina-me a sustentar a verdade com mansidão. Amém.', 145),
	('learning-to-set-boundaries', 6, 'Limites e carinho', 'Limites protegem as relações, e não as afastam.', 'Muita gente teme que limites esfriem os laços. Na prática, eles costumam fortalecê-los, porque o convívio fica mais honesto e leve. Quando você se respeita, as pessoas aprendem como se aproximar com cuidado. Hoje, perceba onde carinho e limite andam juntos.', 'Em qual relação você gostaria de estar mais inteira? Talvez um pequeno ajuste de horário, de tom ou de disponibilidade já traga alívio. Cuidar do vínculo inclui cuidar de você dentro dele, com verdade e sem culpa.', 'Escolha uma relação e defina um pequeno combinado que a proteja.', 'Um bom vínculo tem espaço para você inteira, com tudo o que precisa.', 'Pai, abençoa as pessoas que caminham comigo. Ensina-me a amar sem me perder e a ser próxima sem me anular. Que os meus limites sejam pontes de respeito e que as minhas relações cresçam na verdade e na paz. Amém.', 120),
	('learning-to-set-boundaries', 7, 'Manter seus limites', 'Limites são prática diária, e cada tentativa já é avanço.', 'Colocar limites é aprendizado contínuo. Haverá dias em que você vai ceder e dias em que vai acertar, e ambos fazem parte. O importante é voltar, sem se cobrar demais. Cada vez que escolhe se respeitar, você fortalece a confiança em si mesma.', 'O que mudou em você nestes dias? Observe as pequenas vitórias, mesmo as que passaram quase despercebidas. Você já sabe reconhecer um limite e dizer algo sobre ele. Isso é muito, e merece ser celebrado com carinho.', 'Escreva um limite que quer manter e como vai lembrar dele.', 'Recomeçar faz parte: o que importa é voltar para você.', 'Senhor, obrigada pelo que aprendi. Quando eu falhar, lembra-me de recomeçar sem culpa. Sustenta a minha firmeza e a minha ternura, e que eu viva cada dia fiel ao que tu me chamaste a ser. Amém.', 150),
	('when-your-faith-is-tired', 1, 'Cansaço também é oração', 'Você pode chegar a Deus exatamente como está.', 'Há fases em que orar parece vazio e a fé, uma obrigação distante. Isso não significa que você tenha falhado. O cansaço também pode ser levado a Deus. Hoje, não precisa dizer palavras bonitas: pode apenas chegar e ficar, como em um lugar seguro.', 'Como está a sua relação com a fé neste momento? Seja honesta, sem se julgar. Deus não se assusta com o seu cansaço nem com o seu silêncio. Ele convida quem está cansada a descansar nele, e esse convite continua de pé.', 'Fique um minuto em silêncio e diga a Deus, com suas palavras, como você está.', 'A sinceridade cansada agrada mais a Deus do que a pressa de parecer bem.', 'Deus, estou cansada e nem sei bem como orar. Aceita o meu silêncio e a minha honestidade. Fica comigo neste lugar de pouca força, e me ensina a descansar em ti sem precisar provar nada. Amém.', 135),
	('when-your-faith-is-tired', 2, 'Quando Deus parece calado', 'O silêncio não quer dizer ausência.', 'Há períodos em que a oração parece não ter resposta e o céu, silencioso. Muitas pessoas de fé passaram por isso. O silêncio não prova que Deus se afastou. Às vezes ele é um convite a confiar mais fundo, mesmo sem sentir nada de especial.', 'O que você esperava ouvir ou ver que ainda não veio? Entregue essa espera. Você pode dizer a Deus que o silêncio dói. Os salmos estão cheios de pessoas que clamaram assim e continuaram sendo ouvidas.', 'Leia devagar o Salmo 13 e faça dele a sua oração de hoje.', 'Esperar também é um modo de confiar, mesmo quando é difícil.', 'Senhor, o silêncio pesa, e mesmo assim escolho continuar a falar contigo. Sustenta a minha espera e guarda o meu coração do desânimo. Crê por mim quando eu não conseguir, e lembra-me de que nunca me deixaste sozinha. Amém.', 145),
	('when-your-faith-is-tired', 3, 'Dúvidas não afastam Deus', 'Perguntar e duvidar fazem parte de uma fé viva.', 'Ter dúvidas não é o oposto da fé; muitas vezes é parte dela. Perguntar, questionar e não entender tudo mostra que você leva a sério o que acredita. Deus é grande o bastante para acolher as suas perguntas sem se ofender. Traga-as sem medo.', 'Qual pergunta você tem evitado fazer a Deus? Escreva-a, mesmo que pareça dura. Ela não precisa de resposta hoje. Colocá-la diante dele já é um gesto de confiança, porque você segue conversando e não fugindo.', 'Escreva uma dúvida que você tem e ofereça-a a Deus em oração.', 'Fé madura convive com perguntas e continua caminhando.', 'Pai, tenho perguntas que não sei resolver. Recebe-as com paciência e dá-me o que for preciso para hoje. Ajuda-me a confiar no teu caráter mesmo quando não entendo os teus caminhos. Aumenta a minha fé, na medida da tua graça. Amém.', 150),
	('when-your-faith-is-tired', 4, 'Pequenos sinais de cuidado', 'Procure, no seu dia, sinais discretos do cuidado de Deus.', 'Quando a fé está cansada, é fácil só notar o que falta. Hoje, treine o olhar para o que está presente: uma conversa gentil, um alimento na mesa, um momento de calma. Esses sinais pequenos lembram que o cuidado de Deus costuma chegar em silêncio.', 'Que sinais de cuidado você já percebeu esta semana, mesmo sem dar atenção? Lembrar deles ajuda a fé a respirar. Não é negar a dor, é permitir que a gratidão conviva com ela e reacenda a confiança aos poucos.', 'Anote três sinais de cuidado que você percebeu hoje, por pequenos que sejam.', 'A gratidão treina o olhar a enxergar o que já está ali.', 'Senhor, abre os meus olhos para as tuas bênçãos escondidas no dia a dia. Quando eu só enxergar a falta, lembra-me do que já me deste. Que a gratidão renove a minha fé e me ensine a confiar em ti. Amém.', 125),
	('when-your-faith-is-tired', 5, 'Recomeçar com simplicidade', 'Retome a fé aos poucos, sem cobrança e no seu ritmo.', 'Recomeçar não exige grandes decisões. Pode ser uma oração curta de manhã, um versículo lido com calma, uma conversa com alguém de confiança. A fé se refaz em gestos simples e repetidos. Você não precisa recuperar tudo de uma vez.', 'Que prática simples você gostaria de manter nas próximas semanas? Escolha algo leve e possível. A constância gentil vale mais que o entusiasmo de um dia. Deus acompanha cada pequeno recomeço com alegria, e não com cobrança.', 'Escolha um gesto simples de fé e decida quando vai fazê-lo amanhã.', 'Fé se renova em gestos pequenos repetidos com carinho.', 'Deus fiel, obrigada por não desistires de mim. Ajuda-me a recomeçar com simplicidade, sem pressa e sem culpa. Que eu me volte a ti a cada manhã e encontre na tua presença o descanso e a força de que preciso. Amém.', 140),
	('finding-direction-again', 1, 'Parar para ouvir', 'Antes de decidir, desacelere e crie espaço para escutar.', 'Quando estamos perdidas, a tendência é correr atrás de respostas. Mas a clareza costuma chegar na calma. Hoje, o convite é parar um pouco e criar silêncio por dentro. Você não precisa saber o caminho inteiro; basta estar disposta a ouvir.', 'O que o excesso de barulho tem abafado em você? Pode ser pressa, opiniões alheias ou o medo de errar. No silêncio, o que é essencial tende a aparecer com mais nitidez. Dê a si mesma esse intervalo, sem exigir respostas.', 'Reserve dez minutos sem telas e apenas perceba o que vem à mente.', 'A clareza costuma chegar quando a gente para de correr atrás dela.', 'Senhor, quero ouvir a tua voz no meio de tantas outras. Acalma a minha mente e o meu coração, e mostra-me o que realmente importa. Que eu aprenda a esperar em ti, sem pressa, e a reconhecer o teu caminho. Amém.', 130),
	('finding-direction-again', 2, 'O que realmente importa', 'Lembre dos valores que devem guiar suas escolhas.', 'Direção nasce de valores, e não só de planos. Quando você sabe o que importa de verdade, as escolhas ficam mais claras, mesmo quando o caminho é incerto. Hoje, olhe para aquilo que dá sentido à sua vida e deixe que isso seja a bússola.', 'Em que momentos recentes você sentiu que estava viva e no lugar certo? O que havia ali? Esses sinais mostram o que importa para você. Preste atenção neles: costumam apontar na direção em que vale a pena caminhar.', 'Escreva três coisas que realmente importam para você hoje.', 'Quem conhece seus valores se perde menos nos caminhos.', 'Pai, ajuda-me a distinguir o que é essencial do que é só urgente. Alinha o meu coração com o que tu valorizas e dá-me coragem de viver segundo isso. Que as minhas escolhas reflitam o amor e a verdade que recebi de ti. Amém.', 140),
	('finding-direction-again', 3, 'Soltar o que não é seu', 'Largue expectativas e pesos que não pertencem a você.', 'Às vezes a falta de direção vem de carregar planos que não são nossos: expectativas da família, comparações, cobranças antigas. Hoje, pergunte-se o que você tem sustentado só para agradar. Soltar o que não é seu abre espaço para o que é.', 'Que expectativa tem pesado mais? De onde ela veio? Reconhecer que um peso não é seu já alivia. Você pode honrar as pessoas sem viver a vida que elas imaginaram. Escolher o próprio caminho também é um ato de fé.', 'Nomeie uma expectativa alheia que você decide deixar de carregar.', 'Soltar um peso emprestado deixa as mãos livres para o que é seu.', 'Senhor, entrego a ti as expectativas que não são minhas e os medos que herdei. Livra-me da comparação e da necessidade de aprovação. Mostra-me o caminho que preparaste para mim e dá-me alegria em segui-lo. Amém.', 150),
	('finding-direction-again', 4, 'Pedir sabedoria', 'Peça discernimento e confie que ele virá no tempo certo.', 'A sabedoria é um dom que podemos pedir. Não precisa ser uma oração elaborada: basta reconhecer que precisa de ajuda e se abrir para receber. A resposta pode vir por um versículo, uma conversa ou uma paz serena sobre uma decisão.', 'Qual decisão hoje pede mais discernimento? Traga-a em oração, com todos os prós e contras. Depois, observe onde há mais paz. A paz tranquila costuma ser uma boa companheira nas escolhas, sem pressa de decidir.', 'Ore pedindo sabedoria sobre uma decisão e anote o que sentir depois.', 'Sabedoria vem para quem pede e se dispõe a ouvir.', 'Deus, tu prometes dar sabedoria a quem pede. Peço-te discernimento para as decisões que tenho pela frente. Ilumina o meu pensamento, acalma os meus receios e guia-me por caminhos de paz. Confio que me respondes no teu tempo. Amém.', 145),
	('finding-direction-again', 5, 'Escolher um passo', 'Não é preciso ver tudo: escolha o próximo passo possível.', 'Esperar ter certeza de tudo pode nos paralisar. Hoje, em vez de buscar o mapa completo, escolha só o próximo passo. Um passo pequeno, concreto e possível. Ao caminhar, o caminho se esclarece, e você ganha informação que a espera não daria.', 'Qual seria um passo simples na direção do que importa para você? Talvez uma conversa, uma pesquisa, um pedido de ajuda. Escolha algo que caiba na sua semana. Mover-se com cuidado vale mais do que esperar o momento perfeito.', 'Defina um passo para os próximos três dias e marque quando vai dá-lo.', 'Dar o próximo passo costuma esclarecer o caminho.', 'Senhor, dá-me coragem para dar o próximo passo mesmo sem ver o fim da estrada. Que eu confie que tu guias quem caminha de coração aberto. Corrige-me com ternura se eu me desviar e firma os meus pés no que é bom. Amém.', 125),
	('finding-direction-again', 6, 'Pedir conselho', 'Você não precisa decidir sozinha: busque quem a ajude a ver.', 'Ninguém encontra direção completamente só. Pessoas de confiança enxergam o que não vemos de dentro. Hoje, pense em alguém sábio e honesto, que lhe queira bem, e converse com essa pessoa. Ouvir não obriga a seguir, mas amplia o olhar.', 'Quem, na sua vida, fala a verdade com cuidado? Conversar com essa pessoa pode trazer um alívio inesperado. Você continua responsável pela decisão, mas não precisa carregá-la sozinha. Pedir ajuda também é uma forma de sabedoria.', 'Mande uma mensagem a alguém de confiança e peça uma conversa.', 'Bons conselhos ampliam o olhar, mas a decisão continua sendo sua.', 'Pai, obrigada pelas pessoas que colocaste no meu caminho. Dá-me humildade para pedir ajuda e discernimento para ouvir. Que os conselhos que eu receber me aproximem da verdade e do teu propósito para a minha vida. Amém.', 135),
	('finding-direction-again', 7, 'Caminhar com confiança', 'Siga em frente sabendo que não está sozinha no caminho.', 'Você chegou ao fim destes dias com mais escuta, mais clareza e um passo escolhido. A direção não se resume a um momento: vai se revelando enquanto você caminha. Siga com confiança, ajustando a rota quando preciso, e lembre que não anda sozinha.', 'O que ficou mais claro para você nesta semana? Reconheça o caminho percorrido por dentro. Mesmo que ainda haja incertezas, você agora tem mais ferramentas: silêncio, valores, sabedoria e apoio. Leve-as com você nos próximos dias.', 'Escreva uma frase que resuma a direção que você quer seguir agora.', 'Direção é jornada: ajuste a rota sem perder a esperança.', 'Senhor, obrigada por me guiares nestes dias. Sustenta-me nos próximos passos e ajuda-me a confiar quando a estrada for incerta. Que eu caminhe com paz, sabendo que tua mão me conduz e que tuas promessas permanecem. Amém.', 155);
INSERT INTO `verses` (`position`, `text`, `reference`) VALUES
	(0, '‘Porque sou eu que conheço os planos que tenho para vocês’, diz o Senhor, ‘planos de fazê-los prosperar e não de causar dano…', 'Jeremias 29:11'),
	(1, 'Por isso não tema, pois estou com você; não tenha medo, pois sou o seu Deus.', 'Isaías 41:10'),
	(2, 'O Senhor está perto dos que têm o coração quebrantado e salva os de espírito abatido.', 'Salmos 34:18'),
	(3, 'Venham a mim, todos os que estão cansados e sobrecarregados, e eu lhes darei descanso.', 'Mateus 11:28'),
	(4, 'Deus é o nosso refúgio e a nossa fortaleza, auxílio sempre presente na adversidade.', 'Salmos 46:1'),
	(5, 'O Senhor é o meu pastor; de nada terei falta.', 'Salmos 23:1'),
	(6, 'Confie no Senhor de todo o seu coração e não se apóie em seu próprio entendimento;', 'Provérbios 3:5'),
	(7, 'Seja forte e corajoso! Não se apavore nem desanime, pois o Senhor, o seu Deus, estará com você por onde você andar.', 'Josué 1:9'),
	(8, 'O meu socorro vem do Senhor, que fez os céus e a terra.', 'Salmos 121:2'),
	(9, 'Lancem sobre ele toda a sua ansiedade, porque ele tem cuidado de vocês.', '1 Pedro 5:7'),
	(10, 'Que o Deus da esperança os encha de toda alegria e paz, por sua confiança nele, para que vocês transbordem de esperança, pelo poder do Espírito Santo.', 'Romanos 15:13'),
	(11, 'Graças ao grande amor do Senhor é que não somos consumidos, pois as suas misericórdias são inesgotáveis.', 'Lamentações 3:22'),
	(12, 'Entregue suas preocupações ao Senhor, e ele o susterá; jamais permitirá que o justo venha a cair.', 'Salmos 55:22'),
	(13, 'Mas aqueles que esperam no Senhor renovam as suas forças. Voam alto como águias; correm e não ficam exaustos, andam e não se cansam.', 'Isaías 40:31');
